INSERT INTO blog_posts (category_id, title, slug, excerpt, body, author, status, published_at, seo_title, seo_description) VALUES
(1, 'Connecting Schools, Connecting Lives', 'connecting-schools-connecting-lives',
'Education fairs remain a practical way for families to compare Canadian programs in one place.',
'<p>Education fairs bring school representatives and families into the same room so questions about programs, intakes, and admissions can be answered directly.</p><p>Attendees should arrive with transcripts, a budget range, and a short list of career interests. That preparation makes counselling time more useful.</p>',
'Four Seasons Team', 'published', '2026-09-08 10:00:00', 'Connecting Schools, Connecting Lives', 'How education fairs help families compare Canadian study options.'),
(2, 'Planning a Canadian Study Timeline', 'planning-a-canadian-study-timeline',
'Most successful files start 8–12 months before the intended intake.',
'<p>Language testing, school applications, and visa processing all take time. Starting early reduces last-minute refusals caused by incomplete funds or late medicals.</p>',
'Four Seasons Team', 'published', '2026-08-01 10:00:00', 'Planning a Canadian Study Timeline', 'Suggested timeline for school and study permit applications.'),
(3, 'What Express Entry Actually Measures', 'what-express-entry-actually-measures',
'Language, age, education, and skilled experience still drive ranking.',
'<p>Express Entry rewards documented skilled work and official language results. Informal job titles that do not match duties can weaken a file.</p>',
'Four Seasons Team', 'published', '2026-07-12 10:00:00', 'What Express Entry Actually Measures', 'A plain-language look at CRS factors.');

