INSERT INTO pages (title, slug, body, seo_title, seo_description, status) VALUES
('Who We Are', 'who-we-are',
'<p>Four Seasons Canada is an immigration and international education consultancy. We help clients understand options, assemble complete files, and stay informed through each stage.</p><p>Our work is guided by professional standards, transparent communication, and respect for official Canadian requirements.</p><h2>Mission</h2><p>Deliver ethical, clear, and practical support so clients can make informed decisions about studying, working, visiting, or settling in Canada.</p><h2>Vision</h2><p>Be a trusted advisory option for families pursuing Canadian education and immigration, measured by service quality rather than shortcuts.</p>',
'Who We Are | Four Seasons Canada', 'About Four Seasons Canada, our mission, and our vision.', 1),
('What We Do', 'what-we-do',
'<p>We provide consulting across education, economic immigration, family sponsorship, visitor services, and related status applications.</p><p>Services range from a focused consultation to full representation, depending on what the client needs and what the case requires.</p>',
'What We Do | Four Seasons Canada', 'Overview of consultancy services.', 1),
('Where We Are', 'where-we-are',
'<p>Head office: 90 Burnhamthorpe Rd West, 14th Floor, Sussex Centre, Mississauga, Ontario L5B 3C3.</p><p>Appointments can be booked for phone, video, or in-person meetings during business hours.</p>',
'Where We Are | Four Seasons Canada', 'Office location in Mississauga, Ontario.', 1),
('Privacy Policy', 'privacy-policy',
'<p>Inquiry forms collect contact details so our staff can respond. We do not sell personal information. Records are stored in our database for follow-up and compliance.</p><p>You may email us to request a correction of your contact details.</p>',
'Privacy Policy | Four Seasons Canada', 'How inquiry data is used.', 1);

